// @FIGURE_CODE_BEGIN
/* ---------- constants ---------- */
var MAG = '#e8186c', BLUE = '#1f7fc4', BLK = '#111', FAM = '"Helvetica Neue", Helvetica, Arial, sans-serif';
var PK1 = 2.34, PK2 = 9.69, PI = 6.01;

/* ---------- curve data (monotone cubic through figure control points) ---------- */
var CPX = [0, 0.05, 0.10, 0.15, 0.20, 0.30, 0.40, 0.50, 0.60, 0.70, 0.78, 0.85, 0.90, 0.93, 0.95, 0.97, 0.99, 1.00, 1.01, 1.03, 1.05, 1.08, 1.12, 1.18, 1.25, 1.35, 1.42, 1.50, 1.60, 1.70, 1.80, 1.88, 1.94, 1.98, 2.00];
var CPY = [0.30, 1.30, 1.68, 1.88, 2.02, 2.17, 2.27, 2.34, 2.42, 2.53, 2.66, 2.85, 3.10, 3.45, 3.90, 4.80, 5.70, 6.01, 6.40, 7.15, 7.70, 8.20, 8.62, 8.98, 9.22, 9.48, 9.58, 9.69, 9.84, 10.02, 10.28, 10.58, 10.95, 11.28, 11.55];

function pchip(xs, ys) {
  var n = xs.length, h = [], d = [], i;
  for (i = 0; i < n - 1; i++) { h.push(xs[i + 1] - xs[i]); d.push((ys[i + 1] - ys[i]) / h[i]); }
  var m = new Array(n); m[0] = d[0]; m[n - 1] = d[n - 2];
  for (i = 1; i < n - 1; i++) {
    if (d[i - 1] * d[i] <= 0) m[i] = 0;
    else { var w1 = 2 * h[i] + h[i - 1], w2 = h[i] + 2 * h[i - 1]; m[i] = (w1 + w2) / (w1 / d[i - 1] + w2 / d[i]); }
  }
  return function (x) {
    if (x <= xs[0]) return ys[0];
    if (x >= xs[n - 1]) return ys[n - 1];
    var k = 0; while (x > xs[k + 1]) k++;
    var t = (x - xs[k]) / h[k], t2 = t * t, t3 = t2 * t;
    return ys[k] * (2 * t3 - 3 * t2 + 1) + h[k] * m[k] * (t3 - 2 * t2 + t) + ys[k + 1] * (-2 * t3 + 3 * t2) + h[k] * m[k + 1] * (t3 - t2);
