/* ---------- structures ---------- */
function runsFor(kind) {
  if (kind === 'cation') return [
    { t: 'H', c: MAG, g: 'am' }, { t: '3', c: MAG, sub: 1, g: 'am' }, { t: 'N', g: 'am', key: 'N' }, { t: '+', sup: 1, g: 'am' },
    { t: 'C', key: 'aC' }, { t: 'H' }, { t: 'C', key: 'cC' }, { t: 'O', g: 'ac' }, { t: 'H', c: MAG, g: 'ac' }];
  if (kind === 'zwitter') return [
    { t: 'H', c: MAG, g: 'am' }, { t: '3', c: MAG, sub: 1, g: 'am' }, { t: 'N', g: 'am', key: 'N' }, { t: '+', sup: 1, g: 'am' },
    { t: 'C', key: 'aC' }, { t: 'H' }, { t: 'C', key: 'cC' }, { t: 'O', g: 'ac' }, { t: '\u2013', sup: 1, g: 'ac' }];
  return [
    { t: 'H', c: BLUE, g: 'am' }, { t: '2', c: BLUE, sub: 1, g: 'am' }, { t: 'N', c: BLUE, g: 'am', key: 'N' },
    { t: 'C', key: 'aC' }, { t: 'H' }, { t: 'C', key: 'cC' }, { t: 'O', g: 'ac' }, { t: '\u2013', sup: 1, g: 'ac' }];
}
var CHG = { cation: { t: '+1', c: '#d0021b', bg: 'rgba(208,2,27,0.13)' }, zwitter: { t: '0', c: '#555', bg: 'rgba(0,0,0,0.09)' }, anion: { t: '\u22121', c: '#1f6fb4', bg: 'rgba(31,111,180,0.15)' } };

function speciesW(ctx, kind, fs, charge, bracket) {
  return layoutRuns(ctx, runsFor(kind), fs).w + (charge ? fs * 2.0 : 0) + (bracket ? fs * 1.0 : 0);
}
function pairW(ctx, a, b, fs, charge) {
  ctx.font = fontFor({}, fs);
  var plus = ctx.measureText('+').width;
  return fs * 1.0 + speciesW(ctx, a, fs, charge, false) + fs * 0.55 + plus + fs * 0.55 + speciesW(ctx, b, fs, charge, false);
}
function drawBrackets(ctx, x0, x1, y0, y1, fs) {
  ctx.strokeStyle = BLK; ctx.lineWidth = Math.max(1, fs * 0.07);
  var t = fs * 0.3;
  seg(ctx, x0, y0, x0, y1); seg(ctx, x0, y0, x0 + t, y0); seg(ctx, x0, y1, x0 + t, y1);
  seg(ctx, x1, y0, x1, y1); seg(ctx, x1, y0, x1 - t, y0); seg(ctx, x1, y1, x1 - t, y1);
}
function drawSpecies(ctx, x, yc, kind, fs, opt) {
  opt = opt || {};
  var runs = runsFor(kind), L = layoutRuns(ctx, runs, fs);
  var pad = opt.bracket ? fs * 0.5 : 0;
  var mainX = x + pad, base = yc + fs * 0.30;
  var top = base - fs * 2.32, bot = base + fs * 2.38;

  if (opt.charge) {
    var am = L.groups.am, ac = L.groups.ac;
    if (am) {
      ctx.fillStyle = (kind === 'anion') ? 'rgba(31,127,196,0.15)' : 'rgba(208,2,27,0.14)';
      rrect(ctx, mainX + am[0] - fs * 0.12, base - fs * 1.05, am[1] - am[0] + fs * 0.24, fs * 1.4, fs * 0.2); ctx.fill();
    }
    if (ac) {
      ctx.fillStyle = (kind === 'cation') ? 'rgba(208,2,27,0.12)' : 'rgba(31,111,180,0.16)';
      rrect(ctx, mainX + ac[0] - fs * 0.12, base - fs * 1.05, ac[1] - ac[0] + fs * 0.24, fs * 1.4, fs * 0.2); ctx.fill();
    }
  }
  paintRuns(ctx, mainX, base, runs, fs);

  var cC = mainX + L.keys.cC, aC = mainX + L.keys.aC;
  ctx.strokeStyle = BLK; ctx.lineWidth = Math.max(1, fs * 0.065);
  seg(ctx, cC - fs * 0.09, base - fs * 1.42, cC - fs * 0.09, base - fs * 0.95);
  seg(ctx, cC + fs * 0.09, base - fs * 1.42, cC + fs * 0.09, base - fs * 0.95);
  ctx.font = fontFor({}, fs); ctx.fillStyle = BLK; ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';
  ctx.fillText('O', cC, base - fs * 1.52);
  ctx.textAlign = 'left';
  seg(ctx, aC, base + fs * 0.28, aC, base + fs * 1.22);
  var ch3 = [{ t: 'C' }, { t: 'H' }, { t: '3', sub: 1 }];
  var wch = layoutRuns(ctx, ch3, fs).w;
  paintRuns(ctx, aC - wch / 2, base + fs * 2.02, ch3, fs);

  var w = L.w + 2 * pad;
  if (opt.charge) {
    var b = CHG[kind], bw = fs * 1.6, bh = fs * 0.92, bx = mainX + L.w + fs * 0.35, by = base - fs * 0.95;
    ctx.fillStyle = b.bg; rrect(ctx, bx, by, bw, bh, fs * 0.28); ctx.fill();
    ctx.strokeStyle = b.c; ctx.lineWidth = Math.max(1, fs * 0.055); ctx.stroke();
    ctx.fillStyle = b.c; ctx.font = 'bold ' + (fs * 0.66).toFixed(1) + 'px ' + FAM;
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(b.t, bx + bw / 2, by + bh / 2 + fs * 0.03);
    ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
    w += fs * 2.0;
  }
  if (opt.bracket) drawBrackets(ctx, x, x + w, top, bot, fs);
  return { x0: x, x1: x + w, y0: top, y1: bot };
}
function drawPair(ctx, x, yc, kA, kB, fs, opt) {
  opt = opt || {};
  var pad = fs * 0.5, gap = fs * 0.55;
  ctx.font = fontFor({}, fs);
  var plusW = ctx.measureText('+').width;
  var a = drawSpecies(ctx, x + pad, yc, kA, fs, { bracket: false, charge: opt.charge });
  ctx.fillStyle = BLK; ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic'; ctx.font = fontFor({}, fs);
  ctx.fillText('+', a.x1 + gap, yc + fs * 0.30);
  var b = drawSpecies(ctx, a.x1 + gap + plusW + gap, yc, kB, fs, { bracket: false, charge: opt.charge });
  var x1 = b.x1 + pad;
  drawBrackets(ctx, x, x1, a.y0, a.y1, fs);
  return { x0: x, x1: x1, y0: a.y0, y1: a.y1 };
}

/* ---------- chart ---------- */
var container = document.getElementById('container');
var canvas = document.createElement('canvas');
canvas.style.cssText = 'width:100%;height:100%;display:block';
container.appendChild(canvas);

var bgPlugin = {
  id: 'bg',
  beforeDraw: function (chart) {
    var ca = chart.chartArea; if (!ca) return;
    var c = chart.ctx; c.save();
    c.fillStyle = '#ddeffa';
    c.fillRect(ca.left, ca.top, ca.right - ca.left, ca.bottom - ca.top);
    c.restore();
  }
};
var padPlugin = {
  id: 'pad',
  beforeLayout: function (chart) {
    var W = chart.width, H = chart.height;
    chart.options.layout.padding = {
      left: Math.max(16, W * 0.020),
      right: Math.round(W * 0.552),
      top: Math.max(10, H * 0.035),
      bottom: Math.max(4, H * 0.015)
    };
  }
};
var mainPlugin = { id: 'alanine', afterDatasetsDraw: function (chart) { drawAll(chart); } };

var chart = new Chart(canvas.getContext('2d'), {
  type: 'line',
  data: { datasets: [{ data: CURVE, borderColor: '#e8186c', borderWidth: 3.2, pointRadius: 0, fill: false, tension: 0, parsing: false }] },
  options: {
    responsive: true, maintainAspectRatio: false, animation: false,
    interaction: { mode: null }, events: [],
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    layout: { padding: 0 },
    scales: {
      x: {
        type: 'linear', min: 0, max: 2,
        grid: { color: '#a9bcc8', lineWidth: 1, drawTicks: true, tickColor: '#000', tickLength: 6 },
        border: { color: '#000', width: 1.4 },
        ticks: {
          stepSize: 0.5, color: '#000', autoSkip: false,
          callback: function (v) { return Number(v).toFixed(1); },
          font: function (c) { return { size: Math.max(8, Math.min(15, c.chart.width * 0.0125)), family: FAM }; }
        },
        title: {
          display: true, text: 'Equivalents of HO\u207B', color: '#000',
          font: function (c) { return { size: Math.max(9, Math.min(16, c.chart.width * 0.0135)), family: FAM }; }
        }
      },
      y: {
        type: 'linear', min: 0, max: 12,
        grid: { color: '#a9bcc8', lineWidth: 1, drawTicks: true, tickColor: '#000', tickLength: 6 },
        border: { color: '#000', width: 1.4 },
        ticks: {
          stepSize: 2, color: '#000', autoSkip: false,
          font: function (c) { return { size: Math.max(8, Math.min(15, c.chart.width * 0.0125)), family: FAM }; }
        }
      }
    }
  },
  plugins: [padPlugin, bgPlugin, mainPlugin]
});

/* ---------- master drawing ---------- */
function drawAll(chart) {
  var ctx = chart.ctx, ca = chart.chartArea, W = chart.width, H = chart.height;
  var xs = chart.scales.x, ys = chart.scales.y;
  var X = function (v) { return xs.getPixelForValue(v); };
  var Y = function (v) { return ys.getPixelForValue(v); };
  var plotMin = Math.min(ca.right - ca.left, ca.bottom - ca.top);
  hits.length = 0;
  ctx.save();
  ctx.textBaseline = 'alphabetic'; ctx.textAlign = 'left';

  /* y axis label "pH" (horizontal, as in source) */
  var axFs = Math.max(9, Math.min(16, W * 0.0135));
  ctx.font = axFs.toFixed(1) + 'px ' + FAM; ctx.fillStyle = '#000';
  ctx.textAlign = 'right';
  ctx.fillText('pH', ys.left - 3, (ca.top + ca.bottom) / 2 + axFs * 0.35);
  ctx.textAlign = 'left';

  /* structure panel + connector arrows */
  drawPanel(ctx, chart, ca, X, Y, W, H);

  /* landmarks */
  var lm = [
    { id: 'pka1', eq: 0.5, pH: PK1 },
    { id: 'pi', eq: 1.0, pH: PI },
    { id: 'pka2', eq: 1.5, pH: PK2 }
  ];
  var ms = Math.max(3.5, plotMin * 0.017);
  var lw = Math.max(1.4, plotMin * 0.006);
  for (var i = 0; i < lm.length; i++) {
    var px = X(lm[i].eq), py = Y(lm[i].pH);
    if (state.selected === lm[i].id) {
      ctx.beginPath(); ctx.arc(px, py, ms * 2.1, 0, 6.2832);
      ctx.fillStyle = 'rgba(245,166,35,0.22)'; ctx.fill();
      ctx.strokeStyle = '#f5a623'; ctx.lineWidth = lw * 1.2; ctx.stroke();
    }
    ctx.strokeStyle = '#000'; ctx.lineWidth = lw; ctx.lineCap = 'round';
    seg(ctx, px - ms, py - ms, px + ms, py + ms);
    seg(ctx, px - ms, py + ms, px + ms, py - ms);
    hits.push({ cx: px, cy: py, r: ms * 2.6, id: lm[i].id, tip: LMTIP[lm[i].id], title: LMPOP[lm[i].id][0], body: LMPOP[lm[i].id][1] });
  }

  /* landmark labels + curved leaders */
  var lfs = Math.max(8.5, Math.min(16, plotMin * 0.038));
  var ital = { italic: 1 };
  var r1 = [{ t: 'p' }, { t: 'K', italic: 1 }, { t: 'a1', sub: 1 }, { t: ' = 2.34' }];
  var r2a = [{ t: 'Isoelectric' }], r2b = [{ t: 'point = 6.01' }];
  var r3 = [{ t: 'p' }, { t: 'K', italic: 1 }, { t: 'a2', sub: 1 }, { t: ' = 9.69' }];
  drawLabel(ctx, X(0.045), Y(3.95), r1, lfs);
  drawLabel(ctx, X(0.10), Y(7.95), r2a, lfs);
  drawLabel(ctx, X(0.10), Y(7.10), r2b, lfs);
  drawLabel(ctx, X(0.60), Y(11.15), r3, lfs);
  var alw = Math.max(0.9, plotMin * 0.0035);
  curveArrow(ctx, X(0.14), Y(3.55), X(0.22), Y(2.75), X(0.5) - ms * 1.5, Y(PK1) - ms * 1.4, alw);
  curveArrow(ctx, X(0.55), Y(6.85), X(0.78), Y(6.55), X(1.0) - ms * 1.5, Y(PI) - ms * 1.3, alw);
  curveArrow(ctx, X(0.80), Y(10.80), X(1.15), Y(10.35), X(1.5) - ms * 1.5, Y(PK2) - ms * 1.3, alw);

  /* live marker */
  var eq = state.eq, pH = pHof(eq), mx = X(eq), my = Y(pH);
  ctx.setLineDash([4, 4]); ctx.strokeStyle = 'rgba(40,40,40,0.55)'; ctx.lineWidth = 1;
  if (state.interacted || eq > 0) {
    seg(ctx, mx, my, mx, ca.bottom); seg(ctx, ca.left, my, mx, my);
  }
  ctx.setLineDash([]);
  var dr = Math.max(3.2, plotMin * 0.016);
  ctx.beginPath(); ctx.arc(mx, my, dr, 0, 6.2832);
  ctx.fillStyle = '#8c0f42'; ctx.fill();
  ctx.strokeStyle = '#fff'; ctx.lineWidth = Math.max(1.2, dr * 0.35); ctx.stroke();

  if (state.interacted || eq > 0) drawReadout(ctx, ca, X, Y, plotMin, eq, pH);

  ctx.restore();
}

function drawLabel(ctx, x, y, runs, fs) {
  var w = layoutRuns(ctx, runs, fs).w;
  var cx = x, i;
  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic'; ctx.lineJoin = 'round';
  for (i = 0; i < runs.length; i++) {
    var r = runs[i]; ctx.font = fontFor(r, fs);
    var dy = r.sub ? fs * 0.24 : (r.sup ? -fs * 0.45 : 0);
    ctx.strokeStyle = '#fff'; ctx.lineWidth = fs * 0.36; ctx.strokeText(r.t, cx, y + dy);
    cx += ctx.measureText(r.t).width;
  }
  paintRuns(ctx, x, y, runs, fs);
  return { x0: x, x1: x + w, y0: y - fs * 0.9, y1: y + fs * 0.3 };
}
function curveArrow(ctx, x0, y0, cx, cy, x1, y1, lw) {
  ctx.strokeStyle = '#111'; ctx.lineWidth = lw;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.quadraticCurveTo(cx, cy, x1, y1); ctx.stroke();
  arrowHead(ctx, x1, y1, Math.atan2(y1 - cy, x1 - cx), lw * 5);
}

var LMTIP = {
  pka1: 'pKa1 = 2.34 — half-equivalence: 50:50 cation / zwitterion',
  pi: 'Isoelectric point pI = 6.01 — pure zwitterion, net charge 0',
  pka2: 'pKa2 = 9.69 — half-equivalence: 50:50 zwitterion / anion'
};
var LMPOP = {
  pka1: ['Half-equivalence: pH = pK\u2081 = 2.34', 'At 0.5 equivalent of HO\u207B exactly half of the \u2013COOH groups have been deprotonated, so [cation] = [zwitterion]. The Henderson\u2013Hasselbalch equation then gives pH = pK\u2090\u2081, which is why the curve is flat (well buffered) here.'],
  pi: ['Isoelectric point: pI = 6.01', 'One full equivalent converts essentially all \u2013COOH to \u2013COO\u207B while the ammonium group is still protonated, so the zwitterion dominates. Its +1 and \u22121 sites cancel: net charge is zero and the molecule will not migrate in an electric field. pI is the average of the two pK\u2090 values, (2.34 + 9.69)/2 \u2248 6.01.'],
  pka2: ['Half-equivalence: pH = pK\u2090\u2082 = 9.69', 'At 1.5 equivalents half of the \u2013NH\u2083\u207A groups have lost a proton, so [zwitterion] = [anion] and pH = pK\u2090\u2082. This is the second buffering plateau of the titration.']
};
var SPPOP = {
  cation: ['Fully protonated cation (net +1)', 'Below pH ~2, both acidic sites are protonated: the ammonium N (magenta) and the carboxylic acid \u2013COOH. The overall charge is +1, so this species migrates toward the cathode in an electric field.'],
  zwitter: ['Zwitterion (net 0)', 'The carboxylate is deprotonated (\u2013COO\u207B) while the ammonium is still protonated (\u2013NH\u2083\u207A). The two charges cancel, giving zero net charge \u2014 the form that dominates at the isoelectric point, pH 6.01.'],
  anion: ['Fully deprotonated anion (net \u22121)', 'Above pH ~10 both acidic protons are gone: a neutral amine (blue H\u2082N) and a carboxylate. The overall charge is \u22121, so this species migrates toward the anode.'],
  pair1: ['50:50 mixture at pK\u2090\u2081', 'Equal amounts of the +1 cation and the neutral zwitterion coexist at 0.5 equivalent. Because the acid and its conjugate base are equal, pH = pK\u2090\u2081 = 2.34 and the solution resists pH change.'],
  pair2: ['50:50 mixture at pK\u2090\u2082', 'Equal amounts of the neutral zwitterion and the \u22121 anion coexist at 1.5 equivalents, so pH = pK\u2090\u2082 = 9.69 \u2014 the second buffer region.']
};

function drawPanel(ctx, chart, ca, X, Y, W, H) {
  var px0 = ca.right + Math.max(8, W * 0.012);
  var panelW = W - px0 - 6;
  if (panelW < 120) return;
  var fs = Math.min(panelW * 0.037, H * 0.034, 26);
  var guard = 0;
  while (guard++ < 80 && fs > 6 && (pairW(ctx, 'zwitter', 'anion', fs, state.charge) > panelW * 0.58 ||
    speciesW(ctx, 'cation', fs, state.charge, true) > panelW * 0.40)) fs -= 0.4;

  var rows = [
    { f: 0.085, kind: 'single', a: 'anion', eq: 2.0, id: 'anion' },
    { f: 0.285, kind: 'pair', a: 'zwitter', b: 'anion', eq: 1.5, id: 'pair2' },
    { f: 0.480, kind: 'single', a: 'zwitter', eq: 1.0, id: 'zwitter' },
    { f: 0.678, kind: 'pair', a: 'cation', b: 'zwitter', eq: 0.5, id: 'pair1' },
    { f: 0.868, kind: 'single', a: 'cation', eq: 0.0, id: 'cation' }
  ];
  var actRow = null;
  if (state.interacted) {
    var best = 9, bi = -1;
    for (var q = 0; q < rows.length; q++) { var d = Math.abs(rows[q].eq - state.eq); if (d < best) { best = d; bi = q; } }
    if (best <= 0.13) actRow = bi;
  }
  var ms = Math.max(3.5, Math.min(ca.right - ca.left, ca.bottom - ca.top) * 0.017);
  var alw = Math.max(0.9, W * 0.0011);

  for (var i = 0; i < rows.length; i++) {
    var R = rows[i], yc = H * R.f, box, x0;
    if (R.kind === 'single') x0 = px0 + panelW * 0.09;
    else x0 = W - 6 - pairW(ctx, R.a, R.b, fs, state.charge);

    /* connector arrow (drawn under the structure) */
    var tx = X(R.eq), ty = Y(pHof(R.eq));
    var endx = tx + (R.eq === 0 ? 4 : (R.eq === 2 ? 4 : ms * 1.8));
    ctx.strokeStyle = '#111'; ctx.lineWidth = alw;
    ctx.beginPath(); ctx.moveTo(x0 - fs * 0.45, yc); ctx.lineTo(endx, ty); ctx.stroke();
    arrowHead(ctx, endx, ty, Math.atan2(ty - yc, endx - (x0 - fs * 0.45)), alw * 5.2);

    var dim = (actRow !== null && actRow !== i);
    ctx.save(); ctx.globalAlpha = dim ? 0.42 : 1;
    if (R.kind === 'single') box = drawSpecies(ctx, x0, yc, R.a, fs, { bracket: true, charge: state.charge });
    else box = drawPair(ctx, x0, yc, R.a, R.b, fs, { charge: state.charge });
    ctx.restore();

    if (actRow === i) {
      ctx.strokeStyle = '#f5a623'; ctx.lineWidth = Math.max(1.4, fs * 0.09);
      rrect(ctx, box.x0 - fs * 0.35, box.y0 - fs * 0.3, (box.x1 - box.x0) + fs * 0.7, (box.y1 - box.y0) + fs * 0.6, fs * 0.3);
      ctx.stroke();
    }
    hits.push({
      x0: box.x0 - fs * 0.4, x1: box.x1 + fs * 0.4, y0: box.y0 - fs * 0.3, y1: box.y1 + fs * 0.4,
      id: R.id, tip: SPPOP[R.id][0], title: SPPOP[R.id][0], body: SPPOP[R.id][1], eq: R.eq
    });
  }

  /* key */
  var kfs = Math.max(7, fs * 0.52);
  ctx.font = kfs.toFixed(1) + 'px ' + FAM; ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  var ky = H - kfs * 0.55;
  ctx.fillStyle = MAG; ctx.fillText('\u25A0', px0, ky);
  ctx.fillStyle = '#555'; ctx.fillText(' protonated N (H\u2083N\u207A) / acidic H', px0 + kfs, ky);
  var wkey = ctx.measureText(' protonated N (H\u2083N\u207A) / acidic H').width + kfs * 2.2;
  ctx.fillStyle = BLUE; ctx.fillText('\u25A0', px0 + wkey, ky);
  ctx.fillStyle = '#555'; ctx.fillText(' neutral amine (H\u2082N)', px0 + wkey + kfs, ky);
}

function drawReadout(ctx, ca, X, Y, plotMin, eq, pH) {
  var fs = Math.max(7.5, Math.min(13, plotMin * 0.030));
  var f = fracs(pH), q = f[0] - f[2];
  var l1 = eq.toFixed(2) + ' equiv \u00B7 pH ' + pH.toFixed(2);
  var l3 = 'net charge ' + (q >= 0 ? '+' : '') + q.toFixed(2);
  var segs = [
    { t: '+1 ' + Math.round(f[0] * 100) + '%', c: '#d0021b' },
    { t: '  0 ' + Math.round(f[1] * 100) + '%', c: '#444' },
    { t: '  \u22121 ' + Math.round(f[2] * 100) + '%', c: '#1f6fb4' }
  ];
  ctx.font = fs.toFixed(1) + 'px ' + FAM;
  var w2 = 0, i;
  for (i = 0; i < segs.length; i++) w2 += ctx.measureText(segs[i].t).width;
  var w = Math.max(ctx.measureText(l1).width, ctx.measureText(l3).width, w2) + fs * 1.0;
  var x = ca.left + fs * 0.5, y = ca.top + fs * 0.4;
  var h = fs * 4.5;
  ctx.fillStyle = 'rgba(255,255,255,0.92)'; rrect(ctx, x, y, w, h, fs * 0.35); ctx.fill();
  ctx.strokeStyle = '#9aa7b0'; ctx.lineWidth = 1; ctx.stroke();
  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = '#111'; ctx.font = 'bold ' + fs.toFixed(1) + 'px ' + FAM;
  ctx.fillText(l1, x + fs * 0.5, y + fs * 1.25);
  ctx.font = fs.toFixed(1) + 'px ' + FAM;
  var cx = x + fs * 0.5;
  for (i = 0; i < segs.length; i++) { ctx.fillStyle = segs[i].c; ctx.fillText(segs[i].t, cx, y + fs * 2.55); cx += ctx.measureText(segs[i].t).width; }
  ctx.fillStyle = state.charge ? '#111' : '#555';
  ctx.font = (state.charge ? 'bold ' : '') + fs.toFixed(1) + 'px ' + FAM;
  ctx.fillText(l3, x + fs * 0.5, y + fs * 3.85);
}

/* ---------- interaction ---------- */
function render() { chart.update('none'); }

function update_equivalents(v) {
  state.eq = Math.max(0, Math.min(2, v));
  state.interacted = true;
  render();
}
function toggle_viewMode(on) {
  state.charge = !!on;
  state.interacted = true;
  render();
}

function cpos(e) { var r = canvas.getBoundingClientRect(); return { x: e.clientX - r.left, y: e.clientY - r.top }; }
function findHit(mx, my) {
  for (var i = 0; i < hits.length; i++) {
    var h = hits[i];
    if (h.r != null) { if (Math.hypot(mx - h.cx, my - h.cy) <= h.r) return h; }
    else if (mx >= h.x0 && mx <= h.x1 && my >= h.y0 && my <= h.y1) return h;
  }
  return null;
}
canvas.addEventListener('mousemove', function (e) {
  var p = cpos(e), h = findHit(p.x, p.y), ca = chart.chartArea;
  if (h) { canvas.style.cursor = 'pointer'; showTooltip(h.tip, e); return; }
  if (ca && p.x >= ca.left && p.x <= ca.right && p.y >= ca.top && p.y <= ca.bottom) {
    var v = Math.max(0, Math.min(2, chart.scales.x.getValueForPixel(p.x)));
    var py = chart.scales.y.getPixelForValue(pHof(v));
    if (Math.abs(py - p.y) < 14) {
      canvas.style.cursor = 'pointer';
      showTooltip(v.toFixed(2) + ' equiv HO\u207B \u2192 pH ' + pHof(v).toFixed(2) + ' (click to move marker)', e);
      return;
    }
    canvas.style.cursor = 'crosshair'; hideTooltip(); return;
  }
  canvas.style.cursor = 'default'; hideTooltip();
});
canvas.addEventListener('mouseleave', function () { hideTooltip(); });
canvas.addEventListener('click', function (e) {
  var p = cpos(e), h = findHit(p.x, p.y), ca = chart.chartArea;
  if (h) {
    state.selected = (h.r != null) ? h.id : null;
    state.interacted = true;
    if (h.eq != null) { setSlider(h.eq); }
    else if (h.id === 'pka1') setSlider(0.5);
    else if (h.id === 'pi') setSlider(1.0);
    else if (h.id === 'pka2') setSlider(1.5);
    render();
    showPopup(h.title, h.body);
    return;
  }
  if (ca && p.x >= ca.left && p.x <= ca.right && p.y >= ca.top && p.y <= ca.bottom) {
    var v = Math.round(Math.max(0, Math.min(2, chart.scales.x.getValueForPixel(p.x))) / 0.05) * 0.05;
    state.selected = null; setSlider(v); state.interacted = true; render();
  }
});
function setSlider(v) {
  var inp = document.getElementById('equivalentsInput');
  inp.value = v;
  document.getElementById('equivalentsVal').value = (+v).toFixed(2);
  state.eq = +v;
}

/* ---------- demo steps ---------- */
var STEPS = [
  { title: 'Start: fully protonated cation', n: 'With no base added, alanine sits at low pH as the cation: protonated ammonium and intact carboxylic acid, net charge +1.', eq: 0, charge: false, sel: null },
  { title: 'First buffering region: pK\u2090\u2081', n: 'At 0.5 equivalent the carboxylic acid is half neutralized; the solution holds equal amounts of cation and zwitterion and the pH equals pK\u2090\u2081 = 2.34.', eq: 0.5, charge: false, sel: 'pka1' },
  { title: 'Equivalence point: the zwitterion', n: 'One full equivalent converts nearly all the COOH to COO\u207B. The pH leaps through the steep region and settles at 6.01, where the zwitterion dominates.', eq: 1, charge: false, sel: 'pi' },
  { title: 'Why 6.01 is the isoelectric point', n: 'In the net-charge view the +1 ammonium and \u22121 carboxylate cancel: the dominant species carries zero net charge and will not migrate in an electric field.', eq: 1, charge: true, sel: 'pi' },
  { title: 'Second buffering region: pK\u2090\u2082', n: 'At 1.5 equivalents the ammonium group is half deprotonated; zwitterion and anion are present 50:50 and pH = pK\u2090\u2082 = 9.69.', eq: 1.5, charge: false, sel: 'pka2' },
  { title: 'End: fully deprotonated anion', n: 'By 2.0 equivalents both acidic protons are gone, leaving the neutral blue amine and a carboxylate anion with net charge \u22121 near pH 11.5.', eq: 2, charge: true, sel: null }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  var S = STEPS[stepIdx];
  setSlider(S.eq);
  var cb = document.getElementById('viewModeInput');
  cb.checked = S.charge; state.charge = S.charge;
  state.selected = S.sel;
  state.interacted = stepIdx > 0;
  document.getElementById('demoNarration').textContent = S.n;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + '/' + STEPS.length + ' \u00B7 ' + S.title;
  render();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
