<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ---------- constants (ALL data declared before the chart is constructed) ---------- */
var MAG = '#e8186c', BLUE = '#1f7fc4', BLK = '#111', FAM = '"Helvetica Neue", Helvetica, Arial, sans-serif';
var PK1 = 2.34, PK2 = 9.69, PI = 6.01;

var CHG = {
  cation: { t: '+1', c: '#d0021b', bg: 'rgba(208,2,27,0.13)' },
  zwitter: { t: '0', c: '#555555', bg: 'rgba(0,0,0,0.09)' },
  anion: { t: '\u22121', c: '#1f6fb4', bg: 'rgba(31,111,180,0.15)' }
};

var LMTIP = {
  pka1: 'pKa1 = 2.34 \u2014 half-equivalence: 50:50 cation / zwitterion',
  pi: 'Isoelectric point pI = 6.01 \u2014 pure zwitterion, net charge 0',
  pka2: 'pKa2 = 9.69 \u2014 half-equivalence: 50:50 zwitterion / anion'
};

var LMPOP = {
  pka1: ['Half-equivalence: pH = pK\u2090\u2081 = 2.34',
    'At 0.5 equivalent of HO\u207B exactly half of the \u2013COOH groups have been deprotonated, so [cation] = [zwitterion]. The Henderson\u2013Hasselbalch equation then gives pH = pK\u2090\u2081, which is why the curve is flat (well buffered) here.'],
  pi: ['Isoelectric point: pI = 6.01',
    'One full equivalent converts essentially all \u2013COOH to \u2013COO\u207B while the ammonium group is still protonated, so the zwitterion dominates. Its +1 and \u22121 sites cancel: net charge is zero and the molecule will not migrate in an electric field. pI is the average of the two pK\u2090 values, (2.34 + 9.69)/2 \u2248 6.01.'],
  pka2: ['Half-equivalence: pH = pK\u2090\u2082 = 9.69',
    'At 1.5 equivalents half of the \u2013NH\u2083\u207A groups have lost a proton, so [zwitterion] = [anion] and pH = pK\u2090\u2082. This is the second buffering plateau of the titration.']
};

var SPPOP = {
  cation: ['Fully protonated cation (net +1)',
    'Below pH ~2 both acidic sites are protonated: the ammonium N (magenta) and the carboxylic acid \u2013COOH. The overall charge is +1, so this species migrates toward the cathode in an electric field.'],
  zwitter: ['Zwitterion (net 0)',
    'The carboxylate is deprotonated (\u2013COO\u207B) while the ammonium is still protonated (\u2013NH\u2083\u207A). The two charges cancel, giving zero net charge \u2014 the form that dominates at the isoelectric point, pH 6.01.'],
  anion: ['Fully deprotonated anion (net \u22121)',
    'Above pH ~10 both acidic protons are gone: a neutral amine (blue H\u2082N) and a carboxylate. The overall charge is \u22121, so this species migrates toward the anode.'],
  pair1: ['50:50 mixture at pK\u2090\u2081',
    'Equal amounts of the +1 cation and the neutral zwitterion coexist at 0.5 equivalent. Because the acid and its conjugate base are equal, pH = pK\u2090\u2081 = 2.34 and the solution resists pH change.'],
  pair2: ['50:50 mixture at pK\u2090\u2082',
    'Equal amounts of the neutral zwitterion and the \u22121 anion coexist at 1.5 equivalents, so pH = pK\u2090\u2082 = 9.69 \u2014 the second buffer region.']
};

/* ---------- curve data (monotone cubic through figure control points) ---------- */
var CPX = [0, 0.05, 0.10, 0.15, 0.20, 0.30, 0.40, 0.50, 0.60, 0.70, 0.78, 0.85, 0.90, 0.93, 0.95, 0.97, 0.99, 1.00, 1.01, 1.03, 1.05, 1.08, 1.12, 1.18, 1.25, 1.35, 1.42, 1.50, 1.60, 1.70, 1.80, 1.88, 1.94, 1.98, 2.00];
var CPY = [0.30, 1.30, 1.68, 1.88, 2.02, 2.17, 2.27, 2.34, 2.42, 2.53, 2.66, 2.85, 3.10, 3.45, 3.90, 4.80, 5.70, 6.01, 6.40, 7.15, 7.70, 8.20, 8.62, 8.98, 9.22, 9.48, 9.58, 9.69, 9.84, 10.02, 10.28, 10.58, 10.95, 11.28, 11.55];

function pchip(xs, ys) {
  var n = xs.length, h = [], d = [], i;
  for (i = 0; i < n - 1; i++) { h.push(xs[i + 1] - xs[i]); d.push((ys[i + 1] - ys[i]) / h[i]); }
  var m = new Array(n); m[0] = d[0]; m[n - 1] = d[n - 2];
  for (i = 1; i < n - 1; i++) {
    if (d[i - 1] * d[i] <= 0) m[i] = 0;
    else { var w1 = 2 * h[i] + h[i - 1], w2 = h[i] + 2 * h[i - 1]; m[i] = (w1 + w2) / (w1 / d[i - 1] + w2 / d[i]); }
  }
  return function (x) {
    if (x <= xs[0]) return ys[0];
    if (x >= xs[n - 1]) return ys[n - 1];
    var k = 0; while (x > xs[k + 1]) k++;
    var t = (x - xs[k]) / h[k], t2 = t * t, t3 = t2 * t;
    return ys[k] * (2 * t3 - 3 * t2 + 1) + h[k] * m[k] * (t3 - 2 * t2 + t) + ys[k + 1] * (-2 * t3 + 3 * t2) + h[k] * m[k + 1] * (t3 - t2);
  };
}
var pHof = pchip(CPX, CPY);
var CURVE = (function () { var a = [], i; for (i = 0; i <= 400; i++) { var x = i / 200; a.push({ x: x, y: pHof(x) }); } return a; })();

function fracs(pH) {
  var h = Math.pow(10, -pH), k1 = Math.pow(10, -PK1), k2 = Math.pow(10, -PK2);
  var D = h * h + k1 * h + k1 * k2;
  return [h * h / D, k1 * h / D, k1 * k2 / D];
}

/* ---------- state ---------- */
var state = { eq: 0, charge: false, interacted: false, selected: null };
var hits = [];

/* ---------- text-run helpers ---------- */
function fontFor(r, fs) {
  var s = (r && (r.sub || r.sup)) ? fs * 0.66 : fs;
  return ((r && r.italic) ? 'italic ' : '') + ((r && r.bold) ? 'bold ' : '') + s.toFixed(1) + 'px ' + FAM;
}
function layoutRuns(ctx, runs, fs) {
  var w = 0, groups = {}, keys = {}, i;
  for (i = 0; i < runs.length; i++) {
    var r = runs[i]; ctx.font = fontFor(r, fs);
    var rw = ctx.measureText(r.t).width;
    if (r.g) { if (!groups[r.g]) groups[r.g] = [w, w + rw]; else groups[r.g][1] = w + rw; }
    if (r.key) keys[r.key] = w + rw / 2;
    w += rw;
  }
  return { w: w, groups: groups, keys: keys };
}
function paintRuns(ctx, x, base, runs, fs) {
  var cx = x, i;
  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic'; ctx.lineJoin = 'round';
  for (i = 0; i < runs.length; i++) {
    var r = runs[i]; ctx.font = fontFor(r, fs);
    var dy = r.sub ? fs * 0.24 : (r.sup ? -fs * 0.46 : 0);
    ctx.fillStyle = r.c || BLK;
    ctx.fillText(r.t, cx, base + dy);
    cx += ctx.measureText(r.t).width;
  }
}
function rrect(ctx, x, y, w, h, r) {
  r = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + r, y); ctx.lineTo(x + w - r, y); ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r); ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h); ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r); ctx.quadraticCurveTo(x, y, x + r, y); ctx.closePath();
}
function seg(ctx, x0, y0, x1, y1) { ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke(); }
function arrowHead(ctx, x, y, ang, s) {
  ctx.beginPath(); ctx.moveTo(x, y);
  ctx.lineTo(x - s * Math.cos(ang - 0.40), y - s * Math.sin(ang - 0.40));
  ctx.lineTo(x - s * Math.cos(ang + 0.40), y - s * Math.sin(ang + 0.40));
  ctx.closePath(); ctx.fillStyle = BLK; ctx.fill();
}

/* ---------- condensed structural formulas ---------- */
function runsFor(kind) {
  if (kind === 'cation') return [
    { t: 'H', c: MAG, g: 'am' }, { t: '3', c: MAG, sub: 1, g: 'am' }, { t: 'N', g: 'am', key: 'N' }, { t: '+', sup: 1, g: 'am' },
    { t: 'C', key: 'aC' }, { t: 'H' }, { t: 'C', key: 'cC' }, { t: 'O', g: 'ac' }, { t: 'H', c: MAG, g: 'ac' }];
  if (kind === 'zwitter') return [
    { t: 'H', c: MAG, g: 'am' }, { t: '3', c: MAG, sub: 1, g: 'am' }, { t: 'N', g: 'am', key: 'N' }, { t: '+', sup: 1, g: 'am' },
    { t: 'C', key: 'aC' }, { t: 'H' }, { t: 'C', key: 'cC' }, { t: 'O', g: 'ac' }, { t: '\u2013', sup: 1, g: 'ac' }];
  return [
    { t: 'H', c: BLUE, g: 'am' }, { t: '2', c: BLUE, sub: 1, g: 'am' }, { t: 'N', c: BLUE, g: 'am', key: 'N' },
    { t: 'C', key: 'aC' }, { t: 'H' }, { t: 'C', key: 'cC' }, { t: 'O', g: 'ac' }, { t: '\u2013', sup: 1, g: 'ac' }];
}

function speciesW(ctx, kind, fs, charge, bracket) {
  return layoutRuns(ctx, runsFor(kind), fs).w + (charge ? fs * 2.0 : 0) + (bracket ? fs * 1.0 : 0);
}
function pairW(ctx, a, b, fs, charge) {
  ctx.font = fontFor({}, fs);
  var plus = ctx.measureText('+').width;
  return fs * 1.0 + speciesW(ctx, a, fs, charge, false) + fs * 0.55 + plus + fs * 0.55 + speciesW(ctx, b, fs, charge, false);
}
function drawBrackets(ctx, x0, x1, y0, y1, fs) {
  ctx.strokeStyle = BLK; ctx.lineWidth = Math.max(1, fs * 0.07);
  var t = fs * 0.3;
  seg(ctx, x0, y0, x0, y1); seg(ctx, x0, y0, x0 + t, y0); seg(ctx, x0, y1, x0 + t, y1);
  seg(ctx, x1, y0, x1, y1); seg(ctx, x1, y0, x1 - t, y0); seg(ctx, x1, y1, x1 - t, y1);
}
function drawSpecies(ctx, x, yc, kind, fs, opt) {
  opt = opt || {};
  var runs = runsFor(kind), L = layoutRuns(ctx, runs, fs);
  var pad = opt.bracket ? fs * 0.5 : 0;
  var mainX = x + pad, base = yc + fs * 0.30;
  var top = base - fs * 2.32, bot = base + fs * 2.38;

  if (opt.charge) {
