    ctx.fillStyle = b.c; ctx.font = 'bold ' + (fs * 0.66).toFixed(1) + 'px ' + FAM;
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(b.t, bx + bw / 2, by + bh / 2 + fs * 0.03);
    ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
    w += fs * 2.0;
  }
  if (opt.bracket) drawBrackets(ctx, x, x + w, top, bot, fs);
  return { x0: x, x1: x + w, y0: top, y1: bot };
}
function drawPair(ctx, x, yc, kA, kB, fs, opt) {
  opt = opt || {};
  var pad = fs * 0.5, gap = fs * 0.55;
  ctx.font = fontFor({}, fs);
  var plusW = ctx.measureText('+').width;
  var a = drawSpecies(ctx, x + pad, yc, kA, fs, { bracket: false, charge: opt.charge });
  ctx.fillStyle = BLK; ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic'; ctx.font = fontFor({}, fs);
  ctx.fillText('+', a.x1 + gap, yc + fs * 0.30);
  var b = drawSpecies(ctx, a.x1 + gap + plusW + gap, yc, kB, fs, { bracket: false, charge: opt.charge });
  var x1 = b.x1 + pad;
  drawBrackets(ctx, x, x1, a.y0, a.y1, fs);
  return { x0: x, x1: x1, y0: a.y0, y1: a.y1 };
}

/* ---------- annotation helpers ---------- */
function drawLabel(ctx, x, y, runs, fs) {
  var w = layoutRuns(ctx, runs, fs).w;
  var cx = x, i;
  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic'; ctx.lineJoin = 'round';
  for (i = 0; i < runs.length; i++) {
    var r = runs[i]; ctx.font = fontFor(r, fs);
    var dy = r.sub ? fs * 0.24 : (r.sup ? -fs * 0.45 : 0);
    ctx.strokeStyle = '#fff'; ctx.lineWidth = fs * 0.40; ctx.strokeText(r.t, cx, y + dy);
    cx += ctx.measureText(r.t).width;
  }
  paintRuns(ctx, x, y, runs, fs);
  return { x0: x, x1: x + w, y0: y - fs * 0.9, y1: y + fs * 0.3 };
}
function curveArrow(ctx, x0, y0, cx, cy, x1, y1, lw) {
  ctx.strokeStyle = '#111'; ctx.lineWidth = lw;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.quadraticCurveTo(cx, cy, x1, y1); ctx.stroke();
  arrowHead(ctx, x1, y1, Math.atan2(y1 - cy, x1 - cx), lw * 5);
}

/* ---------- panel ---------- */
function drawPanel(ctx, ca, X, Y, W, H) {
  var px0 = ca.right + Math.max(8, W * 0.012);
  var panelW = W - px0 - 6;
  if (panelW < 110) return;
  var fs = Math.min(panelW * 0.037, H * 0.034, 26);
  var guard = 0;
  while (guard++ < 90 && fs > 5.5 && (pairW(ctx, 'zwitter', 'anion', fs, state.charge) > panelW * 0.60 ||
    speciesW(ctx, 'cation', fs, state.charge, true) > panelW * 0.42)) fs -= 0.35;

  var rows = [
    { f: 0.085, kind: 'single', a: 'anion', eq: 2.0, id: 'anion' },
    { f: 0.285, kind: 'pair', a: 'zwitter', b: 'anion', eq: 1.5, id: 'pair2' },
    { f: 0.480, kind: 'single', a: 'zwitter', eq: 1.0, id: 'zwitter' },
    { f: 0.678, kind: 'pair', a: 'cation', b: 'zwitter', eq: 0.5, id: 'pair1' },
    { f: 0.868, kind: 'single', a: 'cation', eq: 0.0, id: 'cation' }
  ];
  var actRow = null, q, d, best = 9, bi = -1;
  if (state.interacted) {
    for (q = 0; q < rows.length; q++) { d = Math.abs(rows[q].eq - state.eq); if (d < best) { best = d; bi = q; } }
    if (best <= 0.13) actRow = bi;
  }
  var ms = Math.max(3.2, Math.min(ca.right - ca.left, ca.bottom - ca.top) * 0.017);
  var alw = Math.max(0.8, W * 0.0011);

  for (var i = 0; i < rows.length; i++) {
    var R = rows[i], yc = H * R.f, box, x0;
    if (R.kind === 'single') x0 = px0 + panelW * 0.09;
    else x0 = Math.max(px0, W - 6 - pairW(ctx, R.a, R.b, fs, state.charge));

    var tx = X(R.eq), ty = Y(pHof(R.eq));
    var endx = tx + ((R.eq === 0 || R.eq === 2) ? 4 : ms * 1.8);
    ctx.strokeStyle = '#111'; ctx.lineWidth = alw;
    ctx.beginPath(); ctx.moveTo(x0 - fs * 0.45, yc); ctx.lineTo(endx, ty); ctx.stroke();
    arrowHead(ctx, endx, ty, Math.atan2(ty - yc, endx - (x0 - fs * 0.45)), alw * 5.2);

    var dim = (actRow !== null && actRow !== i);
    ctx.save(); ctx.globalAlpha = dim ? 0.42 : 1;
    if (R.kind === 'single') box = drawSpecies(ctx, x0, yc, R.a, fs, { bracket: true, charge: state.charge });
    else box = drawPair(ctx, x0, yc, R.a, R.b, fs, { charge: state.charge });
    ctx.restore();

    if (actRow === i) {
      ctx.strokeStyle = '#f5a623'; ctx.lineWidth = Math.max(1.3, fs * 0.09);
      rrect(ctx, box.x0 - fs * 0.35, box.y0 - fs * 0.3, (box.x1 - box.x0) + fs * 0.7, (box.y1 - box.y0) + fs * 0.6, fs * 0.3);
      ctx.stroke();
    }
    hits.push({
      x0: box.x0 - fs * 0.4, x1: box.x1 + fs * 0.4, y0: box.y0 - fs * 0.3, y1: box.y1 + fs * 0.4,
      id: R.id, tip: SPPOP[R.id][0], title: SPPOP[R.id][0], body: SPPOP[R.id][1], eq: R.eq
    });
  }

  /* colour key along the bottom of the panel */
  var kfs = Math.max(6.5, Math.min(11, fs * 0.55));
  ctx.font = kfs.toFixed(1) + 'px ' + FAM; ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  var ky = H - kfs * 0.6;
  var t1 = ' protonated N (H\u2083N\u207A) / acidic H';
  ctx.fillStyle = MAG; ctx.fillText('\u25A0', px0, ky);
  ctx.fillStyle = '#555'; ctx.fillText(t1, px0 + kfs, ky);
  var wkey = ctx.measureText(t1).width + kfs * 2.2;
  if (px0 + wkey + kfs * 14 < W) {
    ctx.fillStyle = BLUE; ctx.fillText('\u25A0', px0 + wkey, ky);
    ctx.fillStyle = '#555'; ctx.fillText(' neutral amine (H\u2082N)', px0 + wkey + kfs, ky);
  }
}

function drawReadout(ctx, ca, plotMin, eq, pH) {
  var fs = Math.max(7.5, Math.min(13, plotMin * 0.030));
  var f = fracs(pH), q = f[0] - f[2];
  var l1 = eq.toFixed(2) + ' equiv \u00B7 pH ' + pH.toFixed(2);
  var l3 = 'net charge ' + (q >= 0 ? '+' : '') + q.toFixed(2);
  var segs = [
    { t: '+1 ' + Math.round(f[0] * 100) + '%', c: '#d0021b' },
    { t: '  0 ' + Math.round(f[1] * 100) + '%', c: '#444' },
    { t: '  \u22121 ' + Math.round(f[2] * 100) + '%', c: '#1f6fb4' }
  ];
  ctx.font = fs.toFixed(1) + 'px ' + FAM;
  var w2 = 0, i;
  for (i = 0; i < segs.length; i++) w2 += ctx.measureText(segs[i].t).width;
  var w = Math.max(ctx.measureText(l1).width, ctx.measureText(l3).width, w2) + fs * 1.0;
  var x = ca.right - w - fs * 0.5, y = ca.top + fs * 0.4, h = fs * 4.5;
  ctx.fillStyle = 'rgba(255,255,255,0.93)'; rrect(ctx, x, y, w, h, fs * 0.35); ctx.fill();
  ctx.strokeStyle = '#9aa7b0'; ctx.lineWidth = 1; ctx.stroke();
  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = '#111'; ctx.font = 'bold ' + fs.toFixed(1) + 'px ' + FAM;
  ctx.fillText(l1, x + fs * 0.5, y + fs * 1.25);
  ctx.font = fs.toFixed(1) + 'px ' + FAM;
  var cx = x + fs * 0.5;
  for (i = 0; i < segs.length; i++) { ctx.fillStyle = segs[i].c; ctx.fillText(segs[i].t, cx, y + fs * 2.55); cx += ctx.measureText(segs[i].t).width; }
  ctx.fillStyle = state.charge ? '#111' : '#555';
  ctx.font = (state.charge ? 'bold ' : '') + fs.toFixed(1) + 'px ' + FAM;
  ctx.fillText(l3, x + fs * 0.5, y + fs * 3.85);
}

/* ---------- master drawing ---------- */
function drawAll(chartRef) {
  var ctx = chartRef.ctx, ca = chartRef.chartArea, W = chartRef.width, H = chartRef.height;
  if (!ca) return;
  var xs = chartRef.scales.x, ys = chartRef.scales.y;
  var X = function (v) { return xs.getPixelForValue(v); };
  var Y = function (v) { return ys.getPixelForValue(v); };
  var plotMin = Math.min(ca.right - ca.left, ca.bottom - ca.top);
  hits.length = 0;
  ctx.save();
  ctx.textBaseline = 'alphabetic'; ctx.textAlign = 'left';

  /* horizontal "pH" axis title, as in the source */
  var axFs = Math.max(9, Math.min(16, W * 0.0135));
  ctx.font = axFs.toFixed(1) + 'px ' + FAM; ctx.fillStyle = '#000';
  ctx.textAlign = 'right';
  ctx.fillText('pH', Math.max(axFs * 1.4, ys.left - 4), (ca.top + ca.bottom) / 2 + axFs * 0.35);
  ctx.textAlign = 'left';

  /* right-hand structure panel + connector arrows */
  drawPanel(ctx, ca, X, Y, W, H);

  /* landmark x markers */
  var lm = [
    { id: 'pka1', eq: 0.5, pH: PK1 },
    { id: 'pi', eq: 1.0, pH: PI },
    { id: 'pka2', eq: 1.5, pH: PK2 }
  ];
  var ms = Math.max(3.2, plotMin * 0.017);
  var lw = Math.max(1.3, plotMin * 0.006);
  for (var i = 0; i < lm.length; i++) {
    var px = X(lm[i].eq), py = Y(lm[i].pH);
    if (state.selected === lm[i].id) {
      ctx.beginPath(); ctx.arc(px, py, ms * 2.1, 0, 6.2832);
      ctx.fillStyle = 'rgba(245,166,35,0.22)'; ctx.fill();
      ctx.strokeStyle = '#f5a623'; ctx.lineWidth = lw * 1.2; ctx.stroke();
    }
    ctx.strokeStyle = '#000'; ctx.lineWidth = lw; ctx.lineCap = 'round';
    seg(ctx, px - ms, py - ms, px + ms, py + ms);
    seg(ctx, px - ms, py + ms, px + ms, py - ms);
    hits.push({ cx: px, cy: py, r: ms * 2.6, id: lm[i].id, tip: LMTIP[lm[i].id], title: LMPOP[lm[i].id][0], body: LMPOP[lm[i].id][1] });
  }

  /* landmark labels + curved leader arrows */
  var lfs = Math.max(8, Math.min(16, plotMin * 0.038));
  var r1 = [{ t: 'p' }, { t: 'K', italic: 1 }, { t: 'a1', sub: 1 }, { t: ' = 2.34' }];
  var r2a = [{ t: 'Isoelectric' }], r2b = [{ t: 'point = 6.01' }];
  var r3 = [{ t: 'p' }, { t: 'K', italic: 1 }, { t: 'a2', sub: 1 }, { t: ' = 9.69' }];
  drawLabel(ctx, X(0.045), Y(3.95), r1, lfs);
  drawLabel(ctx, X(0.10), Y(7.95), r2a, lfs);
  drawLabel(ctx, X(0.10), Y(7.10), r2b, lfs);
  drawLabel(ctx, X(0.58), Y(11.15), r3, lfs);
  var alw = Math.max(0.9, plotMin * 0.0035);
  curveArrow(ctx, X(0.14), Y(3.55), X(0.22), Y(2.80), X(0.5) - ms * 1.6, Y(PK1) - ms * 1.4, alw);
  curveArrow(ctx, X(0.55), Y(6.85), X(0.78), Y(6.55), X(1.0) - ms * 1.6, Y(PI) - ms * 1.3, alw);
  curveArrow(ctx, X(0.80), Y(10.80), X(1.15), Y(10.35), X(1.5) - ms * 1.6, Y(PK2) - ms * 1.3, alw);

  /* live marker */
  var eq = state.eq, pH = pHof(eq), mx = X(eq), my = Y(pH);
  if (state.interacted) {
    ctx.setLineDash([4, 4]); ctx.strokeStyle = 'rgba(30,30,30,0.6)'; ctx.lineWidth = 1;
    seg(ctx, mx, my, mx, ca.bottom); seg(ctx, ca.left, my, mx, my);
    ctx.setLineDash([]);
  }
  var dr = Math.max(3.0, plotMin * 0.016);
  ctx.beginPath(); ctx.arc(mx, my, dr, 0, 6.2832);
  ctx.fillStyle = '#8c0f42'; ctx.fill();
  ctx.strokeStyle = '#fff'; ctx.lineWidth = Math.max(1.1, dr * 0.35); ctx.stroke();

  if (state.interacted) drawReadout(ctx, ca, plotMin, eq, pH);

  ctx.restore();
}

/* ---------- chart ---------- */
var container = document.getElementById('container');
var canvas = document.createElement('canvas');
canvas.style.cssText = 'width:100%;height:100%;display:block';
container.appendChild(canvas);

var bgPlugin = {
  id: 'bg',
  beforeDatasetsDraw: function (c) {
    var ca = c.chartArea; if (!ca) return;
    var x = c.ctx; x.save();
    x.fillStyle = '#ddeffa';
    x.fillRect(ca.left, ca.top, ca.right - ca.left, ca.bottom - ca.top);
    x.restore();
  }
};
var padPlugin = {
  id: 'pad',
  beforeLayout: function (c) {
    var W = c.width, H = c.height;
    c.options.layout.padding = {
      left: Math.max(16, W * 0.020),
      right: Math.round(W * 0.552),
      top: Math.max(10, H * 0.035),
      bottom: Math.max(4, H * 0.015)
    };
  }
};
var mainPlugin = { id: 'alanine', afterDatasetsDraw: function (c) { drawAll(c); } };

var chart = new Chart(canvas.getContext('2d'), {
  type: 'line',
  data: { datasets: [{ data: CURVE, borderColor: '#e8186c', borderWidth: 3.2, pointRadius: 0, fill: false, tension: 0, parsing: false }] },
  options: {
    responsive: true, maintainAspectRatio: false, animation: false,
    events: [],
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    layout: { padding: 0 },
    scales: {
      x: {
        type: 'linear', min: 0, max: 2,
        grid: { color: '#a9bcc8', lineWidth: 1, drawTicks: true, tickColor: '#000', tickLength: 6 },
        border: { color: '#000', width: 1.4 },
        ticks: {
          stepSize: 0.5, color: '#000', autoSkip: false,
          callback: function (v) { return Number(v).toFixed(1); },
          font: function (c) { return { size: Math.max(8, Math.min(15, c.chart.width * 0.0125)), family: FAM }; }
        },
        title: {
          display: true, text: 'Equivalents of HO\u207B', color: '#000',
          font: function (c) { return { size: Math.max(9, Math.min(16, c.chart.width * 0.0135)), family: FAM }; }
        }
      },
      y: {
        type: 'linear', min: 0, max: 12,
        grid: { color: '#a9bcc8', lineWidth: 1, drawTicks: true, tickColor: '#000', tickLength: 6 },
        border: { color: '#000', width: 1.4 },
        ticks: {
          stepSize: 2, color: '#000', autoSkip: false,
          font: function (c) { return { size: Math.max(8, Math.min(15, c.chart.width * 0.0125)), family: FAM }; }
        }
      }
    }
  },
  plugins: [padPlugin, bgPlugin, mainPlugin]
});
window.__markRendered();

/* ---------- interaction ---------- */
function render() { chart.update('none'); }

function update_equivalents(v) {
  state.eq = Math.max(0, Math.min(2, v));
  state.interacted = true;
  state.selected = null;
  render();
}
function toggle_viewMode(on) {
  state.charge = !!on;
  render();
}

function setSlider(v) {
  v = Math.max(0, Math.min(2, +v));
  var inp = document.getElementById('equivalentsInput');
  if (inp) inp.value = v;
  var out = document.getElementById('equivalentsVal');
  if (out) out.value = v.toFixed(2);
  state.eq = v;
}

function cpos(e) { var r = canvas.getBoundingClientRect(); return { x: e.clientX - r.left, y: e.clientY - r.top }; }
function findHit(mx, my) {
  for (var i = 0; i < hits.length; i++) {
    var h = hits[i];
    if (h.r != null) {
      var dx = mx - h.cx, dy = my - h.cy;
      if (Math.sqrt(dx * dx + dy * dy) <= h.r) return h;
    } else if (mx >= h.x0 && mx <= h.x1 && my >= h.y0 && my <= h.y1) return h;
  }
  return null;
}
canvas.addEventListener('mousemove', function (e) {
  var p = cpos(e), h = findHit(p.x, p.y), ca = chart.chartArea;
  if (h) { canvas.style.cursor = 'pointer'; showTooltip(h.tip, e); return; }
  if (ca && p.x >= ca.left && p.x <= ca.right && p.y >= ca.top && p.y <= ca.bottom) {
    var v = Math.max(0, Math.min(2, chart.scales.x.getValueForPixel(p.x)));
    var py = chart.scales.y.getPixelForValue(pHof(v));
    if (Math.abs(py - p.y) < 16) {
      canvas.style.cursor = 'pointer';
      showTooltip(v.toFixed(2) + ' equiv HO\u207B \u2192 pH ' + pHof(v).toFixed(2) + ' (click to move the marker)', e);
      return;
    }
    canvas.style.cursor = 'crosshair'; hideTooltip(); return;
  }
  canvas.style.cursor = 'default'; hideTooltip();
});
canvas.addEventListener('mouseleave', function () { hideTooltip(); canvas.style.cursor = 'default'; });
canvas.addEventListener('click', function (e) {
  var p = cpos(e), h = findHit(p.x, p.y), ca = chart.chartArea;
  if (h) {
    state.interacted = true;
    if (h.r != null) {
      state.selected = h.id;
      setSlider(h.id === 'pka1' ? 0.5 : (h.id === 'pi' ? 1.0 : 1.5));
    } else {
      state.selected = null;
      if (h.eq != null) setSlider(h.eq);
    }
    render();
    showPopup(h.title, h.body);
    return;
  }
  if (ca && p.x >= ca.left && p.x <= ca.right && p.y >= ca.top && p.y <= ca.bottom) {
    var v = Math.round(Math.max(0, Math.min(2, chart.scales.x.getValueForPixel(p.x))) / 0.05) * 0.05;
    state.selected = null; setSlider(v); state.interacted = true; render();
  }
});

/* ---------- demo steps ---------- */
var STEPS = [
  { title: 'Fully protonated cation', n: 'With no base added, alanine sits at pH \u22480.3 as the cation: protonated ammonium (magenta) and intact carboxylic acid, net charge +1.', eq: 0, charge: false, sel: null, touched: false },
  { title: 'First buffer: pK\u2090\u2081', n: 'At 0.5 equivalent the carboxylic acid is half neutralized; cation and zwitterion are present 50:50, so pH = pK\u2090\u2081 = 2.34 and the curve is flat.', eq: 0.5, charge: false, sel: 'pka1', touched: true },
  { title: 'Equivalence point: zwitterion', n: 'One full equivalent converts nearly all COOH to COO\u207B. The pH leaps through the steep region and settles at 6.01, where the zwitterion dominates.', eq: 1, charge: false, sel: 'pi', touched: true },
  { title: 'Why 6.01 is the isoelectric point', n: 'In the net-charge view the +1 ammonium and \u22121 carboxylate cancel: the dominant species carries zero net charge and will not migrate in an electric field.', eq: 1, charge: true, sel: 'pi', touched: true },
  { title: 'Second buffer: pK\u2090\u2082', n: 'At 1.5 equivalents the ammonium group is half deprotonated; zwitterion and anion are 50:50 and pH = pK\u2090\u2082 = 9.69. pI is the midpoint of the two pK\u2090 values.', eq: 1.5, charge: false, sel: 'pka2', touched: true },
  { title: 'Fully deprotonated anion', n: 'By 2.0 equivalents both acidic protons are gone, leaving the neutral blue amine and a carboxylate: net charge \u22121 near pH 11.5.', eq: 2, charge: true, sel: null, touched: true }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  var S = STEPS[stepIdx];
  setSlider(S.eq);
  var cb = document.getElementById('viewModeInput');
  if (cb) cb.checked = S.charge;
  state.charge = S.charge;
  state.selected = S.sel;
  state.interacted = S.touched;
  document.getElementById('demoNarration').textContent = S.n;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + '/' + STEPS.length + ' \u00B7 ' + S.title;
  render();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using Chart.js.

CONCEPT: Titrating alanine with hydroxide converts it stepwise from a fully protonated cation through the neutral zwitterion to the carboxylate anion, with the pKa values at half-equivalence points and the isoelectric point at one full equivalent.
KEY INSIGHT (what students should walk away understanding): Each flat stretch of the curve is a 50:50 buffer where pH equals a pKa, and the isoelectric point sits midway between the two pKa values — the one pH where alanine exists almost entirely as the zero-net-charge zwitterion.
DEMO STEPS: 6 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "Titrating alanine with hydroxide converts it stepwise from a fully protonated cation through the neutral zwitterion to the carboxylate anion, with the pKa values at half-equivalence points and the isoelectric point at one full equivalent.",
  "figureType": "line_plot",
  "elements": [
    "Pale blue tinted plot area with light gray gridlines",
    "Vertical axis labeled 'pH', range 0 to 12, labeled ticks every 2 units",
    "Horizontal axis labeled 'Equivalents of HO⁻', range 0.0 to 2.0, labeled ticks every 0.5",
    "Magenta titration curve rising in two sigmoidal legs: shallow buffering near pH 2.34, near-vertical jump at 1.0 equivalent, second buffering plateau near pH 9.69, steep rise toward pH 11.5 at 2.0 equivalents",
    "Black 'x' marker at (0.5, 2.34) with annotation 'pKa1 = 2.34' and curved leader arrow",
    "Black 'x' marker at (1.0, 6.01) with annotation 'Isoelectric point = 6.01' and curved leader arrow",
    "Black 'x' marker at (1.5, 9.69) with annotation 'pKa2 = 9.69' and curved leader arrow",
    "Movable circular marker on the curve tied to the equivalents slider, with pH readout callout",
    "Structure panel at right: bracketed fully protonated cation H3N⁺-CH(CH3)-COOH (ammonium N in magenta, acidic OH in magenta)",
    "Structure panel: bracketed 50:50 pair at pKa1 — cation + zwitterion, joined by '+'",
    "Structure panel: bracketed zwitterion H3N⁺-CH(CH3)-COO⁻ alone",
    "Structure panel: bracketed 50:50 pair at pKa2 — zwitterion + anion, joined by '+'",
    "Structure panel: bracketed fully deprotonated anion H2N-CH(CH3)-COO⁻ (neutral amine N in blue)",
    "Thin black leader arrows from five curve positions (0.0, 0.5, 1.0, 1.5, 2.0 equivalents) to their structures",
    "Net-charge overlay badges (+1, 0, −1) and colored charge markers usable in the charge view",
    "Legend/key noting magenta = protonated ammonium nitrogen, blue = neutral amine nitrogen"
  ],
  "interactions": [
    {
      "id": "equivalents",
      "type": "slider",
      "label": "Equivalents of HO⁻ added",
