/* ---------- master drawing ---------- */
function drawAll(chartRef) {
  var ctx = chartRef.ctx, ca = chartRef.chartArea, W = chartRef.width, H = chartRef.height;
  if (!ca) return;
  var xs = chartRef.scales.x, ys = chartRef.scales.y;
