  hits.length = 0;
  ctx.save();
  ctx.textBaseline = 'alphabetic'; ctx.textAlign = 'left';

  /* horizontal "pH" axis title, as in the source */
  var axFs = Math.max(10, Math.min(18, W * 0.021));
  ctx.font = axFs.toFixed(1) + 'px ' + FAM; ctx.fillStyle = '#000';
  ctx.textAlign = 'right';
  ctx.fillText('pH', Math.max(axFs * 1.5, ys.left - 4), (ca.top + ca.bottom) / 2 + axFs * 0.35);
  ctx.textAlign = 'left';

  /* right-hand structure panel + connector arrows */
  drawPanel(ctx, ca, X, Y, W, H);

  /* landmark x markers */
  var lm = [
    { id: 'pka1', eq: 0.5, pH: PK1 },
    { id: 'pi', eq: 1.0, pH: PI },
    { id: 'pka2', eq: 1.5, pH: PK2 }
  ];
  var ms = Math.max(3.5, plotMin * 0.018);
  var lw = Math.max(1.4, plotMin * 0.0065);
  for (var i = 0; i < lm.length; i++) {
    var px = X(lm[i].eq), py = Y(lm[i].pH);
    if (state.selected === lm[i].id) {
      ctx.beginPath(); ctx.arc(px, py, ms * 2.1, 0, 6.2832);
      ctx.fillStyle = 'rgba(245,166,35,0.22)'; ctx.fill();
      ctx.strokeStyle = '#f5a623'; ctx.lineWidth = lw * 1.2; ctx.stroke();
    }
    ctx.strokeStyle = '#000'; ctx.lineWidth = lw; ctx.lineCap = 'round';
    seg(ctx, px - ms, py - ms, px + ms, py + ms);
    seg(ctx, px - ms, py + ms, px + ms, py - ms);
    hits.push({ cx: px, cy: py, r: ms * 2.7, id: lm[i].id, tip: LMTIP[lm[i].id], title: LMPOP[lm[i].id][0], body: LMPOP[lm[i].id][1] });
  }

  /* landmark labels + curved leader arrows (fonts scale with overall figure width) */
  var annFs = Math.max(10.5, Math.min(19, W * 0.0225));
  var alw = Math.max(1.0, W * 0.0022);

  /* pKa1 */
  var r1 = [{ t: 'p' }, { t: 'K', italic: 1 }, { t: 'a1', sub: 1 }, { t: ' = 2.34' }];
  var b1 = drawLabel(ctx, X(0.035), Y(4.30), r1, annFs);
  curveArrow(ctx, b1.x0 + annFs * 0.55, b1.y1 + annFs * 0.35,
    X(0.16), Y(3.05), X(0.5) - ms * 1.5, Y(PK1) - ms * 1.35, alw);

  /* Isoelectric point — single tight caption block (1.2x leading) */
  var ip1 = [{ t: 'Isoelectric' }], ip2 = [{ t: 'point = 6.01' }];
  var ipY1 = Y(8.30);
  var c1 = drawLabel(ctx, X(0.075), ipY1, ip1, annFs);
  var ipY2 = ipY1 + annFs * 1.20;
  var c2 = drawLabel(ctx, X(0.075), ipY2, ip2, annFs);
  var capR = Math.max(c1.x1, c2.x1);
  curveArrow(ctx, capR - annFs * 0.35, ipY2 + annFs * 0.40,
    (capR + X(1.0)) / 2, ipY2 + annFs * 0.95,
    X(1.0) - ms * 1.5, Y(PI) - ms * 1.2, alw);

  /* pKa2 */
  var r3 = [{ t: 'p' }, { t: 'K', italic: 1 }, { t: 'a2', sub: 1 }, { t: ' = 9.69' }];
  var b3 = drawLabel(ctx, X(0.52), Y(11.25), r3, annFs);
  curveArrow(ctx, b3.x0 + (b3.x1 - b3.x0) * 0.55, b3.y1 + annFs * 0.35,
    X(1.12), Y(10.55), X(1.5) - ms * 1.5, Y(PK2) - ms * 1.25, alw);

  /* live marker (hidden in the untouched default view so step 0 matches the source) */
  var eq = state.eq, pH = pHof(eq), mx = X(eq), my = Y(pH);
  if (state.interacted) {
    ctx.setLineDash([4, 4]); ctx.strokeStyle = 'rgba(30,30,30,0.6)'; ctx.lineWidth = 1;
    seg(ctx, mx, my, mx, ca.bottom); seg(ctx, ca.left, my, mx, my);
    ctx.setLineDash([]);
    var dr = Math.max(3.0, plotMin * 0.017);
    ctx.beginPath(); ctx.arc(mx, my, dr, 0, 6.2832);
    ctx.fillStyle = '#8c0f42'; ctx.fill();
    ctx.strokeStyle = '#fff'; ctx.lineWidth = Math.max(1.1, dr * 0.35); ctx.stroke();
    drawReadout(ctx, ca, W, eq, pH);
  }

  ctx.restore();
}

