  for (var i = 0; i < hits.length; i++) {
    var h = hits[i];
    if (h.r != null) {
      var dx = mx - h.cx, dy = my - h.cy;
      if (Math.sqrt(dx * dx + dy * dy) <= h.r) return h;
    } else if (mx >= h.x0 && mx <= h.x1 && my >= h.y0 && my <= h.y1) return h;
  }
