var STEPS = [
  { title: 'Fully protonated cation', n: 'With no base added, alanine sits at pH \u22480 as the cation: protonated ammonium (magenta) and intact carboxylic acid, net charge +1.', eq: 0, charge: false, sel: null, touched: false },
  { title: 'First buffer: pK\u2090\u2081', n: 'At 0.5 equivalent the carboxylic acid is half neutralized; cation and zwitterion are present 50:50, so pH = pK\u2090\u2081 = 2.34 and the curve is flat.', eq: 0.5, charge: false, sel: 'pka1', touched: true },
  { title: 'Equivalence point: zwitterion', n: 'One full equivalent converts nearly all COOH to COO\u207B. The pH leaps through the steep region and settles at 6.01, where the zwitterion dominates.', eq: 1, charge: false, sel: 'pi', touched: true },
  { title: 'Why 6.01 is the isoelectric point', n: 'In the net-charge view the +1 ammonium and \u22121 carboxylate cancel: the dominant species carries zero net charge and will not migrate in an electric field.', eq: 1, charge: true, sel: 'pi', touched: true },
  { title: 'Second buffer: pK\u2090\u2082', n: 'At 1.5 equivalents the ammonium group is half deprotonated; zwitterion and anion are 50:50 and pH = pK\u2090\u2082 = 9.69. pI is the midpoint of the two pK\u2090 values.', eq: 1.5, charge: false, sel: 'pka2', touched: true },
  { title: 'Fully deprotonated anion', n: 'By 2.0 equivalents both acidic protons are gone, leaving the neutral blue amine and a carboxylate: net charge \u22121 near pH 11.5.', eq: 2, charge: true, sel: null, touched: true }
